cat > probe_len_test.go <<'EOF'
package main

import (
	"testing"
	"time"
)

func TestProbeLenSkipsExpired(t *testing.T) {
	store := NewStore(30 * time.Second)
	now := time.Unix(1000, 0)
	store.now = func() time.Time { return now }
	store.Create("a", "u1")
	now = time.Unix(1010, 0)
	store.Create("b", "u2")

	// Both live.
	if store.Len() != 2 {
		t.Fatalf("len = %d, want 2", store.Len())
	}

	// a expires, b still live: Len must agree with Get.
	now = time.Unix(1035, 0)
	if store.Len() != 1 {
		t.Fatalf("len with one expired = %d, want 1", store.Len())
	}

	// Boundary: a session at EXACTLY ttl is still live (Get uses > ttl).
	store2 := NewStore(30 * time.Second)
	at := time.Unix(5000, 0)
	store2.now = func() time.Time { return at }
	store2.Create("s", "u")
	at = time.Unix(5030, 0)
	if store2.Len() != 1 {
		t.Fatalf("session at exactly ttl must count as live, len = %d", store2.Len())
	}
	if _, err := store.Get("b"); err != nil {
		t.Fatalf("live session unreadable: %v", err)
	}
	if _, err := store.Get("a"); err == nil {
		t.Fatal("expired session still readable")
	}

	// All expired: b was refreshed at its 1035 Get, so it lives to 1065.
	now = time.Unix(1066, 0)
	if store.Len() != 0 {
		t.Fatalf("len all expired = %d, want 0", store.Len())
	}

	// Concurrent safety smoke: Len while writing.
	done := make(chan struct{})
	go func() {
		for i := 0; i < 200; i++ {
			store.Create("c", "u3")
			store.Get("c")
		}
		close(done)
	}()
	for i := 0; i < 100; i++ {
		_ = store.Len()
	}
	<-done
}
EOF
